// ════════════════════════ INIT ════════════════════════

export async function initPartyActions(supabase, state) {
    _supabase = supabase;
    _state = state;

    const root = document.getElementById('pa-actions-root');
    if (!root) return;

    const faction = state.faction;
    if (!faction) {
        root.innerHTML = '<div style="display:flex;align-items:center;justify-content:center;min-height:300px;color:var(--text-dim);">No faction data.</div>';
        return;
    }

    // NOTE: absolute-monarchy crowning is intentionally NOT auto-assigned here.
    // A previous version promoted the first faction to load this page whenever
    // nations.monarch_faction_id was NULL — that meant any new party joining a
    // monarchy (or the next player to refresh after an admin wipe) was silently
    // crowned. Monarchy is now only set via admin tooling, SQL, or the
    // Act-of-Abdication reversal flow. New parties in a monarchy start with 0
    // seats and never become the monarch by side-effect.

    // Bug fix: state.faction was captured at page init (common.js) and never
    // refreshed, so the header's Momentum + Party Funds would drift out of
    // sync with the DB after a tick. The Parties page refetches factions
    // directly, which is why players saw e.g. "9.33 momentum on Parties, 23.3
    // on Actions" for the same faction on the same tick. Pull fresh values
    // here so every render in this module reads live state.
    try {
        const { data: freshFaction } = await _supabase.from('factions')
            .select('momentum, party_funds, seats, action_points, bloc_id')
            .eq('id', faction.id)
            .single();
        if (freshFaction) {
            faction.momentum = freshFaction.momentum ?? faction.momentum;
            faction.party_funds = freshFaction.party_funds ?? faction.party_funds;
            faction.seats = freshFaction.seats ?? faction.seats;
            faction.action_points = freshFaction.action_points ?? faction.action_points;
            faction.bloc_id = freshFaction.bloc_id ?? null;
        }
    } catch (err) {
        console.warn('[PartyActions] faction refresh failed, using cached state:', err);
    }

    // Fetch platforms + agitator + opposition status + electoral standing +
    // fundraise count + active coalition (for caretaker gating on PM actions)
    const [myPlat, nationPlat, agitatorResult, oppositionResult, standingResult, coalition] = await Promise.all([
        _supabase.from('faction_platforms').select('*').eq('faction_id', faction.id).order('slot'),
        _supabase.from('faction_platforms').select('*').eq('nation_id', state.nation?.id),
        fetchActiveAgitator(_supabase, faction.id),
        getGoverningStatus(_supabase, state.nation?.id, faction.id),
        _supabase.from('faction_electoral_standing')
            .select('visibility, raw_appeal')
            .eq('faction_id', faction.id)
            .eq('nation_id', state.nation?.id)
            .maybeSingle(),
        fetchActiveCoalition(_supabase, state.nation?.id),
    ]);
    // Populate caretaker flag on the nation so the action-locking check at
    // render time (Call Early Elections / Resign as PM) sees it. Without
    // this, both actions stayed clickable after the legislature dissolved.
    if (state.nation) {
        state.nation.__coalition_status = coalition?.status || null;
    }
    if (myPlat.error) console.error('[PartyActions] Failed to load faction platforms:', myPlat.error.message);
    if (nationPlat.error) console.error('[PartyActions] Failed to load nation platforms:', nationPlat.error.message);
    _myPlatforms = myPlat.data || [];
    _nationPlatforms = nationPlat.data || [];
    _agitator = agitatorResult;
    _isOpposition = oppositionResult.isOpposition;
    _administration = oppositionResult.administration;
    _standing = standingResult.data || null;

    // loadNoConfidenceState reads _administration.pm_party_id — must run after
    // _administration is set above, otherwise cooldown silently skips on first load.
    await loadFundraiseCount();
    await loadNoConfidenceState();

    // Fetch deputy leader
    const { data: deputyData } = await _supabase.from('faction_deputies')
        .select('*').eq('faction_id', faction.id).eq('status', 'active').maybeSingle();
    _deputy = deputyData || null;

    // Fetch lawsuits if agitator is hired
    if (_agitator) {
        _lawsuits = await fetchActiveLawsuits(_supabase, faction.id);
    }

    // Bloc membership + pending invitations (Phase 1)
    await loadBlocState(faction.id, state.nation?.id);

    renderPage(root);
}

/**
 * Classify the given faction's executive role in its nation. Used as the
 * gating predicate for actions that structurally conflict with holding
 * executive power (Create Bloc, Disband Party). Mirrors the three EXISTS
 * checks in the server-side create_bloc / disband_party RPCs.
 */
function classifyHeadOfGovernment(faction) {
    if (!faction) return { isPM: false, isPresident: false, isMonarchActing: false };
    return {
        isPM: !!_administration && _administration.pm_party_id === faction.id,
        isPresident: _state?.nation?.hos_election_method === 'elected'
            && _administration?.president_party_id === faction.id,
        isMonarchActing: isAbsoluteMonarchy(_state?.nation)
            && _state?.nation?.monarch_faction_id === faction.id,
    };
}

// ═══════════════════════════ BLOCS ═══════════════════════════

/**
 * Refresh the three bloc-related state slots: `_myBloc`, `_myBlocIsLeader`,
 * and `_pendingBlocInvites`. Safe to call any time — catches its own errors
 * and leaves state unchanged on failure.
 */
async function loadBlocState(factionId, nationId) {
    if (!factionId || !nationId) {
        _myBloc = null; _myBlocIsLeader = false; _pendingBlocInvites = [];
        return;
    }
    try {
        // Pending invitations addressed to this faction, with bloc + inviter names
        const { data: invites, error: invErr } = await _supabase
            .from('bloc_invitations')
            .select('id, bloc_id, invited_by_faction_id, created_at_tick, status, bloc:bloc_id(id,name,leader_faction_id), inviter:invited_by_faction_id(id,faction_name,party_color)')
            .eq('invited_faction_id', factionId)
            .eq('status', 'pending')
            .order('created_at_tick', { ascending: false });
        if (invErr) throw invErr;
        _pendingBlocInvites = invites || [];

        // Current bloc (if any)
        const blocId = _state?.faction?.bloc_id || null;
        if (blocId) {
            const { data: bloc, error: blocErr } = await _supabase
                .from('blocs')
                .select('*')
                .eq('id', blocId)
                .is('dissolved_at_tick', null)
                .maybeSingle();
            if (blocErr) throw blocErr;
            if (bloc) {
                const { data: members } = await _supabase
                    .from('factions')
                    .select('id, faction_name, seats, party_color, leader_first_name, leader_last_name')
                    .eq('bloc_id', bloc.id)
                    .order('seats', { ascending: false });
                _myBloc = { ...bloc, members: members || [] };
                _myBlocIsLeader = (bloc.leader_faction_id === factionId);
            } else {
                _myBloc = null; _myBlocIsLeader = false;
            }
        } else {
            _myBloc = null; _myBlocIsLeader = false;
        }
    } catch (err) {
        console.warn('[PartyActions] loadBlocState failed:', err?.message || err);
    }
}

/**
 * Small inline chip shown next to the leader's name when they're in a bloc.
 * Keeps the existing detail header layout intact when not in a bloc.
 */
function renderBlocTag(partyColor) {
    if (!_myBloc) return '';
    const leaderBadge = _myBlocIsLeader
        ? `<span style="margin-left:6px;font-family:var(--font-mono);font-size:7px;color:${partyColor};letter-spacing:0.08em;">LEADER</span>`
        : '';
    return `<span class="pa-bloc-tag" style="display:inline-flex;align-items:center;padding:2px 8px;background:${partyColor}18;border:1px solid ${partyColor}55;color:${partyColor};font-family:var(--font-mono);font-size:9px;font-weight:700;letter-spacing:0.08em;text-transform:uppercase;">
        BLOC &middot; ${esc(_myBloc.name)}${leaderBadge}
    </span>`;
}

/**
 * Full bloc detail banner below the header: lists members (name + seats) so
 * the player can see who's in their bloc at a glance. Phase 1 display only
 * — no momentum numbers yet.
 */
function renderBlocBanner(partyColor) {
    if (!_myBloc) return '';
    const members = _myBloc.members || [];
    const totalSeats = members.reduce((s, m) => s + (Number(m.seats) || 0), 0);
    const memberChips = members.map(m => {
        const isLeader = m.id === _myBloc.leader_faction_id;
        const chipColor = m.party_color || partyColor;
        return `<span style="display:inline-flex;align-items:center;gap:6px;padding:3px 8px;border:1px solid ${chipColor}44;border-left:3px solid ${chipColor};background:var(--bg-card);font-family:var(--font-mono);font-size:9px;">
            <span style="color:var(--text-bright);font-weight:700;">${esc(m.faction_name || 'Unknown')}</span>
            <span style="color:var(--text-dim);">${m.seats || 0} seats</span>
            ${isLeader ? `<span style="color:${chipColor};font-weight:700;letter-spacing:0.08em;">LEADER</span>` : ''}
        </span>`;
    }).join('');
    return `<div style="margin:8px 0;padding:8px 12px;background:${partyColor}0a;border:1px solid ${partyColor}33;border-left:3px solid ${partyColor};">
        <div style="display:flex;align-items:center;gap:8px;margin-bottom:6px;">
            <span style="font-family:var(--font-mono);font-size:9px;font-weight:700;color:${partyColor};letter-spacing:0.08em;">BLOC &middot; ${esc(_myBloc.name)}</span>
            <span style="font-family:var(--font-mono);font-size:8px;color:var(--text-dim);">${members.length} member${members.length !== 1 ? 's' : ''} &middot; ${totalSeats} combined seats</span>
        </div>
        <div style="display:flex;flex-wrap:wrap;gap:4px;">${memberChips}</div>
    </div>`;
}

/**
 * Pending bloc invitations addressed to this faction — renders inline cards
 * with Accept / Decline buttons. Click is handled by the delegated listener
 * in renderPage().
 */
function renderBlocInvitationsPanel(partyColor) {
    if (!_pendingBlocInvites || _pendingBlocInvites.length === 0) return '';
    // PostgREST nested relations can come back as either an object or a 1-element array
    // depending on PostgREST/Supabase version. Normalize.
    const firstOrObj = (v) => (Array.isArray(v) ? v[0] : v) || null;
    const cards = _pendingBlocInvites.map(inv => {
        const bloc = firstOrObj(inv.bloc);
        const inviter = firstOrObj(inv.inviter);
        const blocName = bloc?.name || 'a bloc';
        const inviterName = inviter?.faction_name || 'A party leader';
        const inviterColor = inviter?.party_color || partyColor;
        const responding = _blocInviteResponding.has(inv.id);
        return `<div style="margin:6px 0;padding:8px 12px;border:1px solid ${inviterColor}55;border-left:3px solid ${inviterColor};background:${inviterColor}08;display:flex;align-items:center;justify-content:space-between;gap:10px;">
            <div style="flex:1;">
                <div style="font-family:var(--font-mono);font-size:9px;font-weight:700;color:${inviterColor};letter-spacing:0.08em;">BLOC INVITATION</div>
                <div style="font-size:11px;color:var(--text-bright);margin-top:2px;">
                    <strong>${esc(inviterName)}</strong> invites you to join <strong>${esc(blocName)}</strong>.
                </div>
            </div>
            <div style="display:flex;gap:6px;">
                <button class="pa-bloc-invite-btn pa-modal-btn pa-modal-btn--submit" data-invite-id="${esc(inv.id)}" data-decision="accept"${responding ? ' disabled' : ''}>Accept</button>
                <button class="pa-bloc-invite-btn pa-modal-btn pa-modal-btn--cancel" data-invite-id="${esc(inv.id)}" data-decision="decline"${responding ? ' disabled' : ''}>Decline</button>
            </div>
        </div>`;
    }).join('');
    return `<div style="margin:10px 0 4px;">${cards}</div>`;
}

/**
 * Sync the locally-cached faction stats that Phase 2a bloc RPCs mutate —
 * bloc_id (create / accept / leave) and momentum (+2 on join, -7 on leave).
 * Silent no-op on fetch failure: the RPC already succeeded server-side,
 * a failed refresh just leaves the header stale until the next render.
 */
async function _refreshFactionAfterBlocAction(factionId) {
    const { data } = await _supabase.from('factions')
        .select('bloc_id, momentum').eq('id', factionId).single();
    if (!data) return;
    _state.faction.bloc_id = data.bloc_id || null;
    if (data.momentum != null) _state.faction.momentum = data.momentum;
}

/**
 * Accept or decline a pending bloc invitation. Calls the corresponding RPC,
 * refreshes bloc state, and re-renders the panel.
 */
async function respondToBlocInvite(inviteId, decision, root) {
    try {
        const factionId = _state?.faction?.id;
        if (!factionId) throw new Error('No active faction');
        const rpcName = decision === 'accept' ? 'accept_bloc_invite' : 'decline_bloc_invite';
        const paramKey = decision === 'accept' ? 'p_accepting_faction_id' : 'p_declining_faction_id';
        const { data, error } = await _supabase.rpc(rpcName, {
            p_invitation_id: inviteId,
            [paramKey]: factionId
        });
        if (error) throw error;
        if (data && data.success === false) throw new Error(data.error || 'Unknown error');

        await _refreshFactionAfterBlocAction(factionId);
        await loadBlocState(factionId, _state.nation?.id);
        renderPage(root);
    } catch (err) {
        console.error('[PartyActions] respondToBlocInvite failed:', err);
        alert(decision === 'accept'
            ? `Could not accept invitation: ${err.message || err}`
            : `Could not decline invitation: ${err.message || err}`);
    }
}

/**
 * Confirm-and-leave current bloc. Leader-leave dissolves the whole bloc;
 * the RPC handles that branching server-side. Guarded against double-click
 * with `_leaveBlocSubmitting`.
 */
async function triggerLeaveBloc(root) {
    if (!_myBloc) return;
    if (_leaveBlocSubmitting) return;

    const bloc = _myBloc;
    const msg = _myBlocIsLeader
        ? `Leaving ${bloc.name} will DISSOLVE the entire bloc. All ${bloc.members?.length || 0} members will be removed and pending invitations rescinded.\n\nProceed?`
        : `Leave the ${bloc.name} bloc?`;
    if (!confirm(msg)) return;

    _leaveBlocSubmitting = true;
    try {
        const { data, error } = await _supabase.rpc('leave_bloc', {
            p_faction_id: _state.faction.id
        });
        if (error) throw error;
        if (data && data.success === false) throw new Error(data.error || 'Unknown error');

        await _refreshFactionAfterBlocAction(_state.faction.id);
        await loadBlocState(_state.faction.id, _state.nation?.id);
        renderPage(root);
    } catch (err) {
        console.error('[PartyActions] leave_bloc failed:', err);
        alert(`Could not leave bloc: ${err.message || err}`);
    } finally {
        _leaveBlocSubmitting = false;
    }
}

/**
 * Create Bloc modal — name input + selectable list of eligible parties with
 * leader / seats / top 2 ideologies / eligibility badge. At least one invitee
 * must be selected; $100k is charged on Create.
 */
async function openCreateBlocModal(root) {
    const overlay = document.getElementById('pa-bloc-modal');
    if (!overlay) return;
    if (_myBloc) return; // safety

    const faction = _state.faction;
    const partyColor = faction?.color || '#c8a832';

    overlay.innerHTML = `
        <div class="pa-modal" style="width:640px;max-height:85vh;overflow:hidden;display:flex;flex-direction:column;">
            <div class="pa-modal-header">
                <div class="pa-modal-header-left">
                    <div class="pa-modal-dot" style="background:${partyColor};"></div>
                    <span class="pa-modal-title">Create Bloc</span>
                </div>
                <button class="pa-modal-close" id="pa-bloc-close">&times;</button>
            </div>
            <div class="pa-modal-body" style="gap:14px;overflow-y:auto;">
                <div>
                    <div class="pa-modal-step-label">1 &mdash; Bloc Name</div>
                    <input class="pa-modal-input" id="pa-bloc-name" type="text" maxlength="40" placeholder="e.g. Popular Front, United Left, Patriots' Union" style="font-family:var(--font-ui);font-size:12px;">
                    <div style="display:flex;justify-content:space-between;margin-top:3px;">
                        <span id="pa-bloc-name-count" style="font-family:var(--font-mono);font-size:7px;color:var(--text-dim);">0 / 40</span>
                        <span style="font-family:var(--font-mono);font-size:7px;color:var(--text-dim);">Required &middot; up to 40 characters</span>
                    </div>
                </div>
                <div>
                    <div class="pa-modal-step-label">2 &mdash; Invite Parties</div>
                    <div id="pa-bloc-party-list" style="display:flex;flex-direction:column;gap:4px;">
                        <div style="padding:10px;font-family:var(--font-mono);font-size:9px;color:var(--text-dim);">Loading parties...</div>
                    </div>
                </div>
                <div style="padding:6px 10px;background:var(--amber-faint);border:1px solid var(--amber-border);">
                    <div style="font-family:var(--font-mono);font-size:8px;color:var(--accent);margin-bottom:2px;">COST</div>
                    <div style="font-size:9px;color:var(--text-dim);line-height:1.5;">
                        Founding a bloc costs <strong style="color:var(--accent);">$100k</strong>. You become the bloc leader and the listed parties receive invitations they can accept or decline. Any party in your nation that isn't already in a bloc can be invited.
                    </div>
                </div>
            </div>
            <div class="pa-modal-footer">
                <button class="pa-modal-btn pa-modal-btn--cancel" id="pa-bloc-cancel">Cancel</button>
                <button class="pa-modal-btn pa-modal-btn--submit" id="pa-bloc-submit" disabled>Create Bloc &amp; Send Invites</button>
            </div>
        </div>
    `;

    overlay.classList.add('active');

    const selectedInvitees = new Set();
    let eligibleParties = [];

    const close = () => overlay.classList.remove('active');
    document.getElementById('pa-bloc-close')?.addEventListener('click', close);
    document.getElementById('pa-bloc-cancel')?.addEventListener('click', close);
    overlay.addEventListener('click', (e) => { if (e.target === overlay) close(); });

    // Fetch eligible parties + ideology for the current nation
    try {
        const nationId = _state.nation?.id;
        const { data: parties } = await _supabase.from('factions')
            .select('id, faction_name, seats, party_color, leader_first_name, leader_last_name, leader_age, bloc_id')
            .eq('nation_id', nationId)
            .eq('faction_type', 'party')
            .is('abandoned_at', null);
        const partyList = (parties || []).filter(p => p.id !== faction.id);

        // Phase 5b: bloc-creation modal no longer displays per-party
        // ideology axes. Phase 5c will repurpose this row for sector
        // strongholds; for now the row shows leader + seats only.
        eligibleParties = partyList;

        const listEl = document.getElementById('pa-bloc-party-list');
        if (!listEl) return;
        if (partyList.length === 0) {
            listEl.innerHTML = `<div style="padding:10px;font-family:var(--font-mono);font-size:9px;color:var(--text-dim);">No other parties in this nation.</div>`;
            return;
        }

        listEl.innerHTML = partyList.map(p => {
            const pColor = p.party_color || '#7a7a7a';
            const leaderName = (p.leader_first_name && p.leader_last_name)
                ? `${p.leader_first_name} ${p.leader_last_name}` : 'Party Leader';

            // The only ineligibility check left is "already in a bloc" —
            // ideological-distance gating was removed (any parties can ally).
            const ineligible = p.bloc_id ? 'Already in a bloc' : null;

            return `<label class="pa-bloc-party-row" data-party-id="${esc(p.id)}" data-ineligible="${ineligible ? '1' : '0'}"
                style="display:flex;align-items:center;gap:10px;padding:8px 10px;border:1px solid var(--border-mid);border-left:3px solid ${pColor};cursor:${ineligible ? 'not-allowed' : 'pointer'};opacity:${ineligible ? '0.45' : '1'};">
                <input type="checkbox" class="pa-bloc-party-check" ${ineligible ? 'disabled' : ''} style="margin:0;">
                <div style="flex:1;display:flex;flex-direction:column;gap:2px;">
                    <div style="display:flex;align-items:baseline;gap:8px;">
                        <span style="font-family:var(--font-mono);font-size:11px;font-weight:700;color:var(--text-bright);">${esc(p.faction_name)}</span>
                        <span style="font-family:var(--font-mono);font-size:8px;color:var(--text-dim);">${p.seats || 0} seats</span>
                    </div>
                    <div style="font-size:9px;color:var(--text-secondary);">${esc(leaderName)}</div>
                    ${ineligible ? `<div style="font-family:var(--font-mono);font-size:8px;color:var(--orange);margin-top:3px;">${ineligible}</div>` : ''}
                </div>
            </label>`;
        }).join('');

        listEl.addEventListener('change', (e) => {
            const row = e.target.closest('.pa-bloc-party-row');
            if (!row) return;
            if (row.dataset.ineligible === '1') {
                e.target.checked = false;
                return;
            }
            const pid = row.dataset.partyId;
            if (e.target.checked) selectedInvitees.add(pid);
            else selectedInvitees.delete(pid);
            updateSubmitState();
        });
    } catch (err) {
        console.error('[PartyActions] Create Bloc modal fetch failed:', err);
        const listEl = document.getElementById('pa-bloc-party-list');
        if (listEl) listEl.innerHTML = `<div style="padding:10px;font-family:var(--font-mono);font-size:9px;color:var(--red);">Failed to load parties: ${esc(err.message || String(err))}</div>`;
    }

    const nameInput = document.getElementById('pa-bloc-name');
    const submitBtn = document.getElementById('pa-bloc-submit');
    const countEl = document.getElementById('pa-bloc-name-count');
    const updateSubmitState = () => {
        const name = (nameInput?.value || '').trim();
        if (countEl) countEl.textContent = `${name.length} / 40`;
        if (submitBtn) submitBtn.disabled = !(name.length > 0 && selectedInvitees.size > 0) || _createBlocSubmitting;
    };
    nameInput?.addEventListener('input', updateSubmitState);

    submitBtn?.addEventListener('click', async () => {
        if (_createBlocSubmitting) return;
        const name = (nameInput?.value || '').trim();
        if (name.length === 0 || selectedInvitees.size === 0) return;
        _createBlocSubmitting = true;
        submitBtn.disabled = true;
        submitBtn.textContent = 'Creating...';
        try {
            const { data, error } = await _supabase.rpc('create_bloc', {
                p_leader_faction_id: faction.id,
                p_name: name,
                p_invitee_faction_ids: Array.from(selectedInvitees)
            });
            if (error) throw error;
            if (data && data.success === false) throw new Error(data.error || 'Unknown error');

            // Deduct $100k locally so the header re-renders immediately.
            // Momentum (+2 leader founding bonus) and bloc_id come from the
            // post-RPC refresh helper.
            _state.faction.party_funds = Math.max(0, (_state.faction.party_funds || 0) - 100000);
            await _refreshFactionAfterBlocAction(faction.id);
            close();
            await loadBlocState(faction.id, _state.nation?.id);
            renderPage(root);
        } catch (err) {
            console.error('[PartyActions] create_bloc failed:', err);
            alert(`Could not create bloc: ${err.message || err}`);
            submitBtn.disabled = false;
            submitBtn.textContent = 'Create Bloc & Send Invites';
        } finally {
            _createBlocSubmitting = false;
        }
    });
}

// ════════════════════════ RENDER ════════════════════════

/**
 * Phase 2c: leader-only modal to invite an additional party to an existing
 * bloc. Lighter than openCreateBlocModal — no name input, no $100k cost,
 * no multi-select. Just a picker of eligible parties (server enforces full
 * eligibility; client-side filter is best-effort to avoid showing parties
 * we already know can't accept).
 */
async function openInviteToBlocModal(root) {
    if (!_myBloc || !_myBlocIsLeader) return;
    const overlay = document.getElementById('pa-bloc-modal');
    if (!overlay) return;
    const partyColor = _state.faction?.color || '#c8a832';

    overlay.innerHTML = `
        <div class="pa-modal" style="width:520px;max-height:75vh;overflow:hidden;display:flex;flex-direction:column;">
            <div class="pa-modal-header">
                <div class="pa-modal-header-left">
                    <div class="pa-modal-dot" style="background:${partyColor};"></div>
                    <span class="pa-modal-title">Invite to ${esc(_myBloc.name)}</span>
                </div>
                <button class="pa-modal-close" id="pa-blinv-close">&times;</button>
            </div>
            <div class="pa-modal-body" style="gap:10px;overflow-y:auto;">
                <div style="font-size:10px;color:var(--text-dim);line-height:1.5;">
                    Pick a party to invite. Parties already in a bloc, currently in government, or pending an invitation are filtered out.
                </div>
                <div id="pa-blinv-list" style="display:flex;flex-direction:column;gap:4px;">
                    <div style="padding:10px;font-family:var(--font-mono);font-size:9px;color:var(--text-dim);">Loading parties…</div>
                </div>
            </div>
            <div class="pa-modal-footer">
                <button class="pa-modal-btn pa-modal-btn--cancel" id="pa-blinv-cancel">Close</button>
            </div>
        </div>`;
    overlay.classList.add('active');

    const close = () => overlay.classList.remove('active');
    document.getElementById('pa-blinv-close')?.addEventListener('click', close);
    document.getElementById('pa-blinv-cancel')?.addEventListener('click', close);
    overlay.addEventListener('click', (e) => { if (e.target === overlay) close(); });

    const nationId = _state.nation?.id;
    const listEl = document.getElementById('pa-blinv-list');
    if (!listEl || !nationId) return;

    try {
        // bloc_id pre-filter trims the obvious ineligibles client-side; the
        // RPC's _faction_in_active_government check is the authoritative gate.
        const { data: parties, error } = await _supabase.from('factions')
            .select('id, faction_name, seats, party_color, bloc_id')
            .eq('nation_id', nationId)
            .eq('faction_type', 'party')
            .is('abandoned_at', null)
            .is('bloc_id', null);
        if (error) {
            listEl.innerHTML = `<div style="padding:10px;font-family:var(--font-mono);font-size:9px;color:var(--red);">Failed to load parties: ${esc(error.message)}</div>`;
            return;
        }
        const eligible = (parties || []).filter(p => p.id !== _state.faction.id);
        if (eligible.length === 0) {
            listEl.innerHTML = `<div style="padding:10px;font-family:var(--font-mono);font-size:9px;color:var(--text-dim);">No eligible parties to invite.</div>`;
            return;
        }
        listEl.innerHTML = eligible.map(p => {
            const c = p.party_color || '#888';
            return `<div class="pa-blinv-row" data-faction-id="${esc(p.id)}" style="padding:8px 10px;border:1px solid ${c}33;border-left:3px solid ${c};display:flex;justify-content:space-between;align-items:center;cursor:pointer;background:var(--bg-card);">
                <div>
                    <div style="font-size:11px;color:var(--text-bright);font-weight:600;">${esc(p.faction_name || 'Unknown')}</div>
                    <div style="font-family:var(--font-mono);font-size:8px;color:var(--text-dim);">${p.seats || 0} seats</div>
                </div>
                <button class="pa-modal-btn pa-modal-btn--submit pa-blinv-send" data-faction-id="${esc(p.id)}">Invite</button>
            </div>`;
        }).join('');

        listEl.addEventListener('click', async (ev) => {
            const btn = ev.target.closest('.pa-blinv-send');
            if (!btn) return;
            const inviteeId = btn.dataset.factionId;
            if (!inviteeId) return;
            btn.disabled = true; btn.textContent = 'Sending…';
            try {
                const { error: rpcErr } = await _supabase.rpc('invite_to_bloc', {
                    p_bloc_id: _myBloc.id,
                    p_invitee_faction_id: inviteeId,
                });
                if (rpcErr) throw rpcErr;
                btn.textContent = 'Invited';
                await loadBlocState(_state.faction.id, _state.nation?.id);
                renderPage(root);
            } catch (err) {
                console.warn('[PartyActions] invite_to_bloc failed:', err);
                alert(`Could not invite: ${err.message || err}`);
                btn.disabled = false; btn.textContent = 'Invite';
            }
        });
    } catch (e) {
        console.warn('[PartyActions] openInviteToBlocModal threw:', e);
        listEl.innerHTML = `<div style="padding:10px;font-family:var(--font-mono);font-size:9px;color:var(--red);">Unexpected error.</div>`;
    }
}

function renderPage(root) {
    const faction = _state.faction;
    const nation = _state.nation;
    const _isMonarchy = isAbsoluteMonarchy(nation);
    const _isMonarch = _isMonarchy && nation?.monarch_faction_id === faction?.id;
    const partyColor = faction.color || '#c8a832';
    const leaderName = faction.leader_first_name && faction.leader_last_name
        ? `${faction.leader_first_name} ${faction.leader_last_name}` : 'Unknown Leader';
    const seats = faction.seats || 0;
    const totalSeats = nation?.total_seats || 120;
    const seatPct = totalSeats > 0 ? Math.round((seats / totalSeats) * 100) : 0;
    const ap = faction.action_points ?? 0;
    const approval = faction.approval_rating ?? 0;
    const momentum = faction.momentum ?? 50;
    const partyFunds = faction.party_funds ?? 0;

    // Platform slots display with promise progress
    const promiseProgress = getPromiseProgress(_myPlatforms, nation);
    const slotData = [];
    for (let i = 1; i <= 3; i++) {
        const p = _myPlatforms.find(fp => fp.slot === i);
        if (p) {
            const def = PLATFORMS.find(d => d.id === p.platform_key);
            const pp = promiseProgress.find(pr => pr.id === p.id);
            const metCount = pp ? pp.stats.filter(s => s.met).length : 0;
            const totalCount = pp ? pp.stats.length : 0;
            slotData.push({ name: def?.name || p.platform_key, status: p.status, metCount, totalCount, slot: i });
        } else {
            slotData.push(null);
        }
    }

    // Platforms status item — stringify the per-slot state so the shell
    // can render opaquely. Status icon + class mapping stays here
    // because it's party-specific (fulfilled/failed/abated states).
    const platformItems = slotData.map(s => {
        if (!s) return { label: 'No Platform' };
        const statusIcon = s.status === 'fulfilled' ? ' ✓'
            : s.status === 'failed' ? ' ✗'
            : s.status === 'abated' ? ' —' : '';
        const statusClass = s.status === 'fulfilled' ? 'fulfilled'
            : s.status === 'failed' ? 'failed'
            : s.status === 'abated' ? 'abated' : 'filled';
        const progress = s.totalCount > 0 ? ` (${s.metCount}/${s.totalCount})` : '';
        return {
            label: s.name + progress + statusIcon,
            statusClass,
            title: `${s.metCount} of ${s.totalCount} stats on target`,
        };
    });

    // Party Funds display ($X.XM / $Xk / raw) — preserved from prior inline code.
    const fundsFmt = '$' + (partyFunds >= 1000000
        ? (partyFunds / 1000000).toFixed(1) + 'M'
        : partyFunds >= 1000 ? Math.round(partyFunds / 1000) + 'k' : partyFunds);
    // Monarchy headline stat is now Crown Authority (consolidated from
    // public_approval as part of the Phase 8 monarchy-stat unification).
    // Non-monarchy keeps the existing Nat. Approval (gov_approval) read.
    const approvalValue = _isMonarchy
        ? Math.round(Number(_state.nation?.crown_authority ?? 50))
        : Math.round(Number(_state.nation?.gov_approval ?? 0));

    renderRoleActionsShell(root, {
        title: _isMonarch ? 'Royal Court' : 'Party Actions',
        entityName: faction.faction_name,
        entityColor: partyColor,
        stats: [
            { label: 'Party Funds', value: fundsFmt, color: 'var(--accent)' },
            { label: 'Momentum', value: Number(momentum).toFixed(1), color: momentum > 0 ? 'var(--text-bright)' : 'var(--red)' },
            { label: _isMonarchy ? 'Crown Authority' : 'Nat. Approval', value: String(approvalValue), color: 'var(--green)' },
        ],
        statusBarItems: [
            { type: 'count', label: 'Seats', big: String(seats), bigColor: partyColor, dim1: `/ ${totalSeats}`, dim2: `(${seatPct}%)` },
            { type: 'list', label: 'Platforms', items: platformItems },
        ],
        rolesContainerId: 'pa-leaders',
        panelContainerId: 'pa-actions-panel',
        extraHtml: `
            <div class="pa-modal-overlay" id="pa-statement-modal"></div>
            <div class="pa-modal-overlay" id="pa-platform-modal"></div>
            <div class="pa-modal-overlay" id="pa-hire-modal"></div>
            <div class="pa-modal-overlay" id="pa-lawsuit-modal"></div>
            <div class="pa-modal-overlay" id="pa-appoint-pm-modal"></div>
            <div class="pa-modal-overlay" id="pa-modernize-modal"></div>
            <div class="pa-modal-overlay" id="pa-rebrand-modal"></div>
            <div class="pa-modal-overlay" id="pa-deputy-modal"></div>
            <div class="pa-modal-overlay" id="pa-rally-modal"></div>
            <div class="pa-modal-overlay" id="pa-royal-modal"></div>
            <div class="pa-modal-overlay" id="pa-bloc-modal"></div>
        `,
    });

    document.getElementById('pa-leaders').innerHTML = renderLeaderCards(leaderName, partyColor, faction);
    document.getElementById('pa-actions-panel').innerHTML = renderActionsPanel(leaderName, partyColor, faction);

    // Bind leader card clicks
    document.getElementById('pa-leaders')?.addEventListener('click', (e) => {
        const card = e.target.closest('.pa-leader-card');
        if (!card || card.classList.contains('vacant')) return;
        const role = card.dataset.role;
        if (role && role !== _selectedRole) {
            _selectedRole = role;
            renderPage(root);
        }
    });

    // Bind action clicks
    document.getElementById('pa-actions-panel')?.addEventListener('click', (e) => {
        const item = e.target.closest('.pa-action-item');
        if (!item || item.classList.contains('locked')) return;
        const actionId = item.dataset.actionId;
        if (actionId === 'fundraise') {
            executeFundraise(root);
        } else if (actionId === 'grant_seats') {
            openGrantSeatsModal(root);
        } else if (actionId === 'revoke_seats') {
            openRevokeSeatsModal(root);
        } else if (actionId === 'rally') {
            openRallyModal(root);
        } else if (actionId === 'statement') {
            openStatementModal(root);
        } else if (actionId === 'platform') {
            openPlatformModal(root);
        } else if (actionId === 'file_lawsuit') {
            openLawsuitModal(root);
        } else if (actionId === 'appoint_pm') {
            openAppointPMModal(root);
        } else if (actionId === 'modernize') {
            openModernizeModal(root);
        } else if (actionId === 'rebrand') {
            openRebrandModal(root);
        } else if (actionId === 'no_confidence') {
            triggerNoConfidence();
        } else if (actionId === 'call_snap_election') {
            triggerCallSnapElection();
        } else if (actionId === 'call_early_elections') {
            triggerCallEarlyElections();
        } else if (actionId === 'resign_as_pm') {
            triggerResignAsPM();
        } else if (actionId === 'leave_coalition') {
            triggerLeaveCoalition();
        } else if (actionId === 'disband_party') {
            triggerDisbandParty();
        } else if (actionId === 'create_bloc') {
            openCreateBlocModal(root);
        } else if (actionId === 'leave_bloc') {
            triggerLeaveBloc(root);
        } else if (actionId === 'invite_to_bloc') {
            openInviteToBlocModal(root);
        }
    });

    // Bloc invitation inbox (Accept / Decline buttons render inside the leader panel)
    document.getElementById('pa-actions-panel')?.addEventListener('click', async (e) => {
        const btn = e.target.closest('.pa-bloc-invite-btn');
        if (!btn) return;
        const inviteId = btn.dataset.inviteId;
        const decision = btn.dataset.decision; // 'accept' | 'decline'
        if (!inviteId || !decision) return;
        if (_blocInviteResponding.has(inviteId)) return;
        _blocInviteResponding.add(inviteId);
        try {
            await respondToBlocInvite(inviteId, decision, root);
        } finally {
            _blocInviteResponding.delete(inviteId);
        }
    });

    // Bind hire agitator button
    document.getElementById('pa-hire-agitator-btn')?.addEventListener('click', () => openHireAgitatorModal(root));
    document.getElementById('pa-hire-agitator-panel')?.addEventListener('click', (e) => {
        if (e.target.closest('#pa-hire-agitator-btn')) return;
        openHireAgitatorModal(root);
    });

    // Bind hire deputy button
    document.getElementById('pa-hire-deputy-btn')?.addEventListener('click', () => openHireDeputyModal(root));
    document.getElementById('pa-hire-deputy-panel')?.addEventListener('click', (e) => {
        if (e.target.closest('#pa-hire-deputy-btn')) return;
        openHireDeputyModal(root);
    });
}

function renderLeaderCards(leaderName, partyColor, faction) {
    const _isMonarchLocal = isAbsoluteMonarchy(_state.nation) && _state.nation?.monarch_faction_id === faction?.id;
    return ROLES.map(role => {
        const isLeader = role.id === 'leader';
        const isAgitator = role.id === 'agitator';
        const isActive = _selectedRole === role.id;

        // Agitator: populated if hired, otherwise hireable
        let isVacant, name, portrait, actionCount, roleSubLabel;
        if (isLeader) {
            isVacant = false;
            name = leaderName;
            portrait = initials(faction.leader_first_name, faction.leader_last_name);
            actionCount = LEADER_ACTIONS.length;
            // Determine political role label
            const __isMonarchy = isAbsoluteMonarchy(_state.nation);
            const __isMonarch = __isMonarchy && _state.nation?.monarch_faction_id === faction.id;
            if (__isMonarch) {
                roleSubLabel = { text: (_state.nation?.monarch_title || 'KING').toUpperCase(), color: '#c8a832' };
            } else if (__isMonarchy) {
                roleSubLabel = { text: 'NOBLE HOUSE', color: '#8b9a6b' };
            } else {
                const isPM = _administration?.pm_party_id === faction.id;
                const isPresident = _state.nation?.hos_election_method === 'elected' && _administration?.president_party_id === faction.id;
                if (isPM) roleSubLabel = { text: 'PRIME MINISTER', color: '#5cc55c' };
                else if (isPresident) roleSubLabel = { text: 'PRESIDENT', color: '#5cc55c' };
                else if (!_isOpposition) roleSubLabel = { text: 'GOVERNING', color: '#8b9a6b' };
                else roleSubLabel = { text: 'OPPOSITION', color: '#c84' };
            }
        } else if (isAgitator && _agitator) {
            isVacant = false;
            name = `${_agitator.first_name} ${_agitator.last_name}`;
            portrait = initials(_agitator.first_name, _agitator.last_name);
            actionCount = 1; // File Lawsuit (others coming later)
        } else if (isAgitator && !_agitator) {
            isVacant = false; // not vacant — hireable
            name = 'Not Hired';
            portrait = '+';
            actionCount = 0;
        } else if (role.id === 'deputy' && _deputy) {
            isVacant = false;
            name = `${_deputy.first_name} ${_deputy.last_name}`;
            portrait = initials(_deputy.first_name, _deputy.last_name);
            actionCount = 1; // Rally
        } else if (role.id === 'deputy' && !_deputy) {
            isVacant = false;
            name = 'Not Hired';
            portrait = '+';
            actionCount = 0;
        } else if (role.id === 'campaign') {
            isVacant = false;
            name = 'Campaign Mgr';
            portrait = 'CM';
            actionCount = CAMPAIGN_MANAGER_ACTIONS.length;
        } else {
            isVacant = true;
            name = 'Vacant';
            portrait = '\u2014';
            actionCount = 0;
        }

        const isGovLocked = role.oppositionOnly && !_isOpposition;

        let html = `
            <div class="pa-leader-card ${isActive ? 'active' : ''} ${isVacant ? 'vacant' : ''} ${isGovLocked ? 'vacant' : ''}"
                 data-role="${role.id}"
                 style="${isActive ? `border-left-color:${role.color};` : ''}${isGovLocked ? 'opacity:0.35;' : ''}">
                ${role.oppositionOnly ? `<div style="position:absolute;top:0;right:0;font-family:var(--font-mono);font-size:5px;font-weight:700;letter-spacing:0.04em;padding:1px 4px;color:${isGovLocked ? 'var(--text-dim)' : '#d44a4a'};background:${isGovLocked ? 'rgba(100,100,100,0.1)' : 'rgba(212,74,74,0.1)'};border:1px solid ${isGovLocked ? 'rgba(100,100,100,0.2)' : 'rgba(212,74,74,0.2)'};border-top:none;border-right:none;">${isGovLocked ? 'IN GOVERNMENT' : 'OPPOSITION ONLY'}</div>` : ''}
                <div class="pa-leader-top">
                    <div class="pa-leader-avatar" style="color:${role.color};background:${role.color}15;border-color:${role.color}33;">${portrait}</div>
                    <div class="pa-leader-info">
                        <div class="pa-leader-role">
                            <span class="pa-leader-role-label" style="color:${role.color};">${isLeader && _isMonarchLocal ? (_state.nation?.monarch_title || 'King').toUpperCase() : role.title}</span>
                            ${actionCount > 0 ? `<span class="pa-leader-role-count">${actionCount} actions</span>` : ''}
                        </div>
                        <div class="pa-leader-name">${esc(name)}</div>
                        ${roleSubLabel ? `<div style="font-family:var(--font-mono);font-size:7px;font-weight:700;color:${roleSubLabel.color};margin-top:2px;">${roleSubLabel.text}</div>` : ''}
                        ${isAgitator && _agitator ? `<div style="display:flex;align-items:center;gap:3px;margin-top:2px;"><div style="flex:1;height:2px;background:var(--border-mid);"><div style="height:100%;width:${_agitator.skill}%;background:${getSkillLabel(_agitator.skill).color};"></div></div><span style="font-family:var(--font-mono);font-size:8px;color:var(--text-dim);width:16px;text-align:right;">${_agitator.skill}</span></div>` : ''}
                        ${isAgitator && !_agitator ? '<div style="font-family:var(--font-mono);font-size:7px;color:#d44a4a;margin-top:2px;">Click to recruit</div>' : ''}
                    </div>
                </div>
            </div>
        `;
        return html;
    }).join('') + `
        <div class="pa-threats">
            <div class="pa-threats-title">Threats</div>
            <div class="pa-threats-row">
                <span class="pa-threats-label">Active scandals</span>
                <span class="pa-threats-value">0</span>
            </div>
            <div class="pa-threats-row">
                <span class="pa-threats-label">Media investigations</span>
                <span class="pa-threats-value">0</span>
            </div>
            <div class="pa-threats-row">
                <span class="pa-threats-label">Oppo research against us</span>
                <span class="pa-threats-value">?</span>
            </div>
        </div>
    `;
}

function renderActionsPanel(leaderName, partyColor, faction) {
    const _isMonarchy = isAbsoluteMonarchy(_state.nation);
    const _isMonarch = _isMonarchy && _state.nation?.monarch_faction_id === faction?.id;
    const role = ROLES.find(r => r.id === _selectedRole);
    if (!role) return '';

    const isLeader = _selectedRole === 'leader';
    const isAgitator = _selectedRole === 'agitator';
    const isCampaign = _selectedRole === 'campaign';
    const isDeputy = _selectedRole === 'deputy';
    const isVacant = !isLeader && !isAgitator && !isCampaign && !isDeputy;

    if (isVacant) {
        return `
            <div class="pa-vacant-msg">
                <div>
                    <div class="pa-vacant-title">${esc(role.fullTitle)} — Vacant</div>
                    <div class="pa-vacant-sub">This position has not been filled. Recruitment coming in a future update.</div>
                </div>
            </div>
        `;
    }

    // Agitator: blocked if in government
    if (isAgitator && !_isOpposition) {
        return `
            <div class="pa-vacant-msg" style="opacity:0.4;">
                <div style="text-align:center;">
                    <div style="font-size:2rem;margin-bottom:12px;opacity:0.3;">🚫</div>
                    <div class="pa-vacant-title">Agitator Unavailable</div>
                    <div class="pa-vacant-sub" style="max-width:400px;margin:8px auto;">
                        Your party is in government. The Agitator role is only available to opposition parties.
                    </div>
                </div>
            </div>
        `;
    }

    // Agitator: not hired → show hire prompt
    if (isAgitator && !_agitator) {
        return `
            <div class="pa-vacant-msg" style="cursor:pointer;" id="pa-hire-agitator-panel">
                <div style="text-align:center;">
                    <div style="font-size:2rem;margin-bottom:12px;opacity:0.4;">&#9760;</div>
                    <div class="pa-vacant-title">Hire an Opposition Coordinator</div>
                    <div class="pa-vacant-sub" style="max-width:400px;margin:8px auto 16px;">
                        The Agitator leads your opposition strategy — filing lawsuits, organizing protests, and applying legal and political pressure against the government.
                    </div>
                    <button class="pa-modal-btn pa-modal-btn--submit" id="pa-hire-agitator-btn" style="background:#d44a4a;">Search Candidates</button>
                </div>
            </div>
        `;
    }

    // Agitator: hired → show their actions
    if (isAgitator && _agitator) {
        return renderAgitatorActionsPanel(role);
    }

    // Deputy: not hired → show hire prompt; hired → show Rally action
    if (isDeputy && !_deputy) {
        return `
            <div class="pa-vacant-msg" style="cursor:pointer;" id="pa-hire-deputy-panel">
                <div style="text-align:center;">
                    <div style="font-size:2rem;margin-bottom:12px;opacity:0.4;">🤝</div>
                    <div class="pa-vacant-title">Hire a Deputy Party Leader</div>
                    <div class="pa-vacant-sub" style="max-width:400px;margin:8px auto 16px;">
                        The Deputy supports your party leader — organizing rallies, boosting momentum, and energizing the base.
                    </div>
                    <button class="pa-modal-btn pa-modal-btn--submit" id="pa-hire-deputy-btn" style="background:#8b9a6b;">Search Candidates</button>
                </div>
            </div>
        `;
    }
    if (isDeputy && _deputy) {
        return renderDeputyActionsPanel(role);
    }

    // Campaign Manager: show rebrand action
    if (isCampaign) {
        return renderCampaignManagerPanel(role, faction);
    }

    const portrait = initials(faction.leader_first_name, faction.leader_last_name);
    const age = faction.leader_age ? `, Age ${faction.leader_age}` : '';

    const seats = faction.seats || 0;
    const momentum = faction.momentum ?? 0;

    // Use monarch-specific actions if this is the monarch in a monarchy
    const __isMonarchyForActions = isAbsoluteMonarchy(_state.nation);
    const __isMonarchForActions = __isMonarchyForActions && _state.nation?.monarch_faction_id === faction.id;
    const actionsList = __isMonarchForActions ? MONARCH_ACTIONS : LEADER_ACTIONS;

    const actionsHtml = actionsList.map(action => {
        const tagsHtml = action.tags.map(t =>
            `<span class="pa-action-tag" style="color:${TAG_COLORS[t] || 'var(--text-dim)'};">${t}</span>`
        ).join('');

        // Fundraise: show dynamic cost/yield info
        let extraInfo = '';
        let costDisplay = action.cost;
        let costColor = action.costColor;
        let isDisabled = action.locked;
        // Vote of No Confidence — gated on three things:
        //   1. We must be opposition (PM party can't file against itself)
        //   2. No motion already pending in this nation
        //   3. 12-tick per-PM-party cooldown (loaded into _noConfidenceCooldownTicks)
        if (action.id === 'no_confidence') {
            const isMonarchyNation = isAbsoluteMonarchy(_state.nation);
            const isPMParty = !!_administration && _administration.pm_party_id === faction.id;
            if (isMonarchyNation) {
                // Parliament has no authority to remove the Monarch's PM.
                // Dismissal is a royal prerogative — the Monarch replaces
                // the PM via the Appoint Prime Minister royal action above.
                // Defense in depth: fileNoConfidenceMotion also rejects
                // monarchy nations server-side.
                isDisabled = true;
                action.lockReason = 'Parliament cannot remove the Monarch’s Prime Minister. Only the Monarch can dismiss the PM.';
            } else if (isPMParty) {
                isDisabled = true;
                action.lockReason = 'Your party is the Prime Minister — file from another party.';
            } else if (_noConfidencePending) {
                isDisabled = true;
                action.lockReason = 'A motion of no confidence is already pending in Parliament.';
            } else if (_noConfidenceCooldownTicks > 0) {
                isDisabled = true;
                const t = _noConfidenceCooldownTicks;
                action.lockReason = `Cooldown: ${t} tick${t !== 1 ? 's' : ''} remaining before another motion can be filed against this PM party.`;
            } else if (!_administration || !_administration.pm_party_id) {
                isDisabled = true;
                action.lockReason = 'No active Prime Minister to file against.';
            } else {
                action.lockReason = '';
            }
        } else if (action.id === 'call_early_elections' || action.id === 'resign_as_pm') {
            // Both are PM-only tools for a parliamentary PM. Presidential systems
            // don't have a PM-dissolution mechanic (they run on fixed terms via
            // impeachment), so hide the actions there too by keeping them locked.
            const nation = _state.nation;
            const isParliamentaryPM = hasParliamentaryPM(nation);
            const isMonarchy = isAbsoluteMonarchy(nation);
            const isPMParty = !!_administration && _administration.pm_party_id === faction.id;
            if (isMonarchy) {
                // Absolute monarchy: no parliamentary elections, no PM-led
                // dissolution. Both call_early_elections and resign_as_pm
                // would trigger the parliamentary caretaker + snap-election
                // cascade in resignPM / callEarlyElectionsAction, which is
                // incoherent in monarchy. The Monarch changes the government
                // via the Appoint PM royal action.
                isDisabled = true;
                action.lockReason = action.id === 'call_early_elections'
                    ? 'Elections are not held under absolute monarchy. The Monarch appoints the Prime Minister.'
                    : 'Prime Ministers serve at the Monarch’s pleasure. The Monarch must replace the PM via the Appoint Prime Minister royal action.';
            } else if (!isParliamentaryPM) {
                isDisabled = true;
                action.lockReason = 'Only parliamentary and semi-presidential systems have a PM seat.';
            } else if (!isPMParty) {
                isDisabled = true;
                action.lockReason = 'Prime Minister\u2019s party only.';
            } else if (_state.nation && _state.nation.__coalition_status === 'caretaker') {
                // Optional guard: if the coalition already flipped to caretaker
                // (e.g. another action just fired) the buttons should be inert.
                isDisabled = true;
                action.lockReason = 'Government is already in caretaker mode.';
            } else {
                action.lockReason = '';
            }
        } else if (action.id === 'call_snap_election') {
            // Government-type gate first (no parliament → no snap), then a
            // PM-only gate when a PM is seated. With a sitting PM the
            // action belongs to the head of government; the any-party
            // fallback only applies when the seat is vacant so it still
            // works as a coalition-formation deadlock breaker.
            const nation = _state.nation;
            const isMonarchy = isAbsoluteMonarchy(nation);
            const govType = String(nation?.government_type || '').toLowerCase();
            const isPresidential = govType === 'presidential';
            const pmPartyId = _administration?.pm_party_id || null;
            const isPMParty = !!pmPartyId && pmPartyId === faction.id;
            if (isMonarchy) {
                isDisabled = true;
                action.lockReason = 'Snap elections are not held under absolute monarchy. The Monarch appoints the Prime Minister.';
            } else if (isPresidential) {
                isDisabled = true;
                action.lockReason = 'Presidential systems run on fixed terms — there is no parliamentary election to call.';
            } else if (pmPartyId && !isPMParty) {
                isDisabled = true;
                action.lockReason = 'Only the Prime Minister’s party can call snap elections while a PM is seated.';
            } else {
                action.lockReason = '';
            }
        } else if (action.id === 'leave_coalition') {
            // Parliamentary-only gate + opposition gate + PM-party gate.
            // Server RPC mirrors these, so a client-side bypass still fails.
            const nation = _state.nation;
            const isParliamentaryPM = hasParliamentaryPM(nation);
            const isPMParty = !!_administration && _administration.pm_party_id === faction.id;
            if (!isParliamentaryPM) {
                isDisabled = true;
                action.lockReason = 'Only available in parliamentary systems.';
            } else if (_isOpposition) {
                isDisabled = true;
                action.lockReason = 'You are in opposition.';
            } else if (isPMParty) {
                isDisabled = true;
                action.lockReason = 'Prime Minister’s party cannot leave — resign first.';
            } else {
                action.lockReason = '';
            }
        } else if (action.id === 'disband_party') {
            // Head-of-Government guard mirrors the server RPC. PM / elected
            // President / Monarch must step down first so coalition rows
            // don't dangle with a dead party_id.
            const hog = classifyHeadOfGovernment(faction);
            if (hog.isPM) {
                isDisabled = true;
                action.lockReason = 'You are Prime Minister — resign before disbanding.';
            } else if (hog.isPresident) {
                isDisabled = true;
                action.lockReason = 'You are the sitting President — step down before disbanding.';
            } else if (hog.isMonarchActing) {
                isDisabled = true;
                action.lockReason = 'The reigning monarch cannot disband the royal house.';
            } else {
                action.lockReason = '';
            }
        } else if (action.id === 'fundraise') {
            costDisplay = 'ACTION';
            costColor = '#c8a832';
            extraInfo = `<div style="margin-top:4px;font-family:var(--font-mono);font-size:8px;color:var(--text-dim);display:flex;gap:12px;">
                <span>Themed event · positions you with a voter bloc</span>
                ${_fundraiseUseCount > 0 ? `<span style="color:var(--orange);">Used this tick</span>` : ''}
            </div>`;
            if (_fundraiseUseCount >= 1) {
                isDisabled = true;
                extraInfo += `<div style="margin-top:3px;font-family:var(--font-mono);font-size:9px;color:var(--red);">Already hosted a fundraiser this tick.</div>`;
            }
        }

        return `
            <div class="pa-action-item ${isDisabled ? 'locked' : ''}" data-action-id="${action.id}">
                <div class="pa-action-top">
                    <div style="display:flex;align-items:center;gap:8px;">
                        <span class="pa-action-name">${esc(action.name)}</span>
                        <div class="pa-action-tags">${tagsHtml}</div>
                    </div>
                    <div class="pa-action-right">
                        <span class="pa-action-cost" style="color:${costColor};">${costDisplay}</span>
                    </div>
                </div>
                <div class="pa-action-desc">${esc(action.desc)}</div>
                ${extraInfo}
                ${action.locked && action.lockReason ? `<div style="margin-top:4px;font-family:var(--font-mono);font-size:7px;color:var(--orange);display:flex;align-items:center;gap:4px;"><span>\u2298</span><span>${esc(action.lockReason)}</span></div>` : ''}
            </div>
        `;
    }).join('');

    return `
        <div class="pa-detail-header">
            <div class="pa-detail-left">
                <div class="pa-detail-avatar" style="color:${role.color};background:${role.color}15;border-color:${role.color}33;">${portrait}</div>
                <div>
                    <div style="display:flex;align-items:baseline;gap:6px;flex-wrap:wrap;">
                        <span style="font-family:var(--font-mono);font-size:20px;font-weight:700;color:${role.color};">${_isMonarch ? (_state.nation?.monarch_title || 'KING').toUpperCase() : role.title}</span>
                        <span class="pa-detail-name">${esc(leaderName)}</span>
                        ${_isMonarchy && _state.nation?.dynasty_name ? `<span style="font-family:var(--font-mono);font-size:12px;color:var(--text-dim);font-style:italic;">House ${esc(_state.nation.dynasty_name)}</span>` : ''}
                        ${renderBlocTag(partyColor)}
                    </div>
                    <div class="pa-detail-meta">${_isMonarch ? esc((_state.nation?.monarch_title || 'King') + ' of ' + (_state.nation?.name || '')) : esc(role.fullTitle) + ' &middot; ' + esc(faction.faction_name)}${age}${(() => {
                        if (_isMonarch) return ' <span style="color:#c8a832;font-weight:700;"> &middot; ' + (_state.nation?.monarch_title || 'MONARCH').toUpperCase() + '</span>';
                        if (_isMonarchy) return ' <span style="color:#8b9a6b;font-weight:700;"> &middot; NOBLE HOUSE</span>';
                        const isPM = _administration?.pm_party_id === faction.id;
                        const isPresident = _state.nation?.hos_election_method === 'elected' && _administration?.president_party_id === faction.id;
                        if (isPM) return ' <span style="color:#5cc55c;font-weight:700;"> &middot; PRIME MINISTER</span>';
                        if (isPresident) return ' <span style="color:#5cc55c;font-weight:700;"> &middot; PRESIDENT</span>';
                        if (!_isOpposition) return ' <span style="color:#8b9a6b;font-weight:700;"> &middot; GOVERNING</span>';
                        return ' <span style="color:#c84;font-weight:700;"> &middot; OPPOSITION</span>';
                    })()}</div>
                </div>
            </div>
        </div>
        ${renderBlocInvitationsPanel(partyColor)}
        ${renderBlocBanner(partyColor)}
        <div class="pa-actions-list">
            ${actionsHtml}
        </div>
        <div class="pa-skill-footer">
            <span style="color:${role.color};font-weight:700;">${role.title}</span> actions are executed by the party leader. Effectiveness depends on party approval and momentum.
        </div>
    `;
}

// ════════════════════════ DEPUTY LEADER PANEL ════════════════════════

const DEPUTY_ACTIONS = [
    {
        id: 'rally',
        name: 'Hold a Rally',
        desc: 'Invest party funds into a public rally. Higher investment improves your odds, but a bad roll can backfire. Roll 1d6 + rally bonus for momentum.',
        cost: '$50k-$200k',
        costColor: '#8b9a6b',
        tags: ['CAMPAIGN', 'RISKY'],
        locked: false,
    },
    {
        id: 'create_bloc',
        name: 'Create Bloc',
        desc: 'Found a pre-coalition alliance with other parties. Pick a name and invite any parties in your nation that aren\'t already in a bloc. Phase 1 is formation only — shared momentum, vote discipline, and coalition binding arrive in later phases.',
        cost: '$100k',
        costColor: '#c8a832',
        moneyCost: 100000,
        tags: ['STRATEGIC', 'ALLIANCE'],
        locked: false,
    },
    {
        id: 'leave_bloc',
        name: 'Leave Bloc',
        desc: 'Exit your current bloc. If you are the bloc leader, leaving dissolves the whole bloc and all pending invitations are withdrawn. Greyed out when you are not in a bloc.',
        cost: '$0',
        costColor: 'var(--text-dim)',
        moneyCost: 0,
        tags: ['ALLIANCE'],
        locked: false,
    },
    {
        id: 'invite_to_bloc',
        name: 'Invite Party to Bloc',
        desc: 'Send a bloc invitation to an additional party. Leader-only. Eligible parties are in your nation, not already in a bloc, and not currently in government.',
        cost: '$0',
        costColor: 'var(--text-dim)',
        moneyCost: 0,
        tags: ['ALLIANCE'],
        locked: false,
    },
];

const RALLY_TIERS = [
    { cost: 50000, bonus: 1, label: '$50k (+1)' },
    { cost: 80000, bonus: 2, label: '$80k (+2)' },
    { cost: 120000, bonus: 3, label: '$120k (+3)' },
    { cost: 150000, bonus: 4, label: '$150k (+4)' },
    { cost: 200000, bonus: 5, label: '$200k (+5)' },
];

function getRallyResult(dieRoll, bonus) {
    const total = dieRoll + bonus;
    if (total >= 8) return { momentum: 3, label: 'Rousing Success', color: '#5cc55c' };
    if (total >= 5) return { momentum: 2, label: 'Solid Turnout', color: '#8b9a6b' };
    if (total >= 3) return { momentum: 0, label: 'Flat Response', color: '#ca5' };
    return { momentum: -2, label: 'Backfire', color: '#c55' };
}

function renderDeputyActionsPanel(role) {
    const faction = _state.faction;
    const partyColor = faction?.color || role.color;

    const actionsHtml = DEPUTY_ACTIONS.map(action => {
        const tagsHtml = action.tags.map(t =>
            `<span class="pa-action-tag" style="color:${TAG_COLORS[t] || 'var(--text-dim)'};">${t}</span>`
        ).join('');

        // Bloc action gating mirrors the server-side checks in create_bloc.
        let isDisabled = action.locked;
        let lockReason = '';
        if (action.id === 'create_bloc') {
            const hog = classifyHeadOfGovernment(faction);
            if (_myBloc) {
                isDisabled = true;
                lockReason = `Already in the ${_myBloc.name} bloc.`;
            } else if (hog.isPM || hog.isPresident || hog.isMonarchActing) {
                isDisabled = true;
                lockReason = 'Head of Government cannot form blocs — you already lead the coalition.';
            } else if ((faction.party_funds || 0) < 100000) {
                isDisabled = true;
                lockReason = 'Needs $100k party funds.';
            }
        } else if (action.id === 'leave_bloc') {
            if (!_myBloc) {
                isDisabled = true;
                lockReason = 'You are not in a bloc.';
            } else if (_myBlocIsLeader) {
                lockReason = `Leaving dissolves ${_myBloc.name} — all members will be removed.`;
            }
        } else if (action.id === 'invite_to_bloc') {
            if (!_myBloc) {
                isDisabled = true;
                lockReason = 'You are not in a bloc.';
            } else if (!_myBlocIsLeader) {
                isDisabled = true;
                lockReason = 'Only the bloc leader can send invitations.';
            }
        }

        return `
            <div class="pa-action-item ${isDisabled ? 'locked' : ''}" data-action-id="${action.id}">
                <div class="pa-action-top">
                    <div style="display:flex;align-items:center;gap:8px;">
                        <span class="pa-action-name">${esc(action.name)}</span>
                        <div class="pa-action-tags">${tagsHtml}</div>
                    </div>
                    <div class="pa-action-right">
                        <span class="pa-action-cost" style="color:${action.costColor};">${action.cost}</span>
                    </div>
                </div>
                <div class="pa-action-desc">${esc(action.desc)}</div>
                ${lockReason ? `<div style="margin-top:4px;font-family:var(--font-mono);font-size:7px;color:var(--orange);display:flex;align-items:center;gap:4px;"><span>⊘</span><span>${esc(lockReason)}</span></div>` : ''}
            </div>
        `;
    }).join('');

    const sk = getSkillLabel(_deputy.skill);
    return `
        <div class="pa-detail-header">
            <div class="pa-detail-left">
                <div class="pa-detail-avatar" style="color:${role.color};background:${role.color}15;border-color:${role.color}33;">${initials(_deputy.first_name, _deputy.last_name)}</div>
                <div>
                    <div style="display:flex;align-items:baseline;gap:6px;flex-wrap:wrap;">
                        <span style="font-family:var(--font-mono);font-size:20px;font-weight:700;color:${role.color};">${role.title}</span>
                        <span class="pa-detail-name">${esc(_deputy.first_name)} ${esc(_deputy.last_name)}</span>
                        ${renderBlocTag(partyColor)}
                    </div>
                    <div class="pa-detail-meta">${esc(role.fullTitle)} &middot; Age ${_deputy.age} &middot; Skill: <span style="color:${sk.color};font-weight:700;">${_deputy.skill}</span></div>
                </div>
            </div>
        </div>
        ${renderBlocInvitationsPanel(partyColor)}
        ${renderBlocBanner(partyColor)}
        <div class="pa-actions-list" id="pa-actions-panel">${actionsHtml}</div>
    `;
}

